const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

/** Thrown when a `%` is not followed by two hexadecimal digits. */
export class PercentEncodingError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

/** Thrown when a `resolve` record's base has no scheme. */
export class NoBaseSchemeError extends Error {}

function isHexDigit(ch) {
  return ch !== undefined && /[0-9A-Fa-f]/.test(ch)
}

function isUnreservedChar(ch) {
  return /^[A-Za-z0-9\-._~]$/.test(ch)
}

function asciiLower(s) {
  return s.replace(/[A-Z]/g, (c) => String.fromCharCode(c.charCodeAt(0) + 32))
}

/**
 * Splits a URI reference into its five generic components. Absent
 * components are `null`; a present-but-empty component is `''`. The path
 * is always present, possibly empty.
 */
export function parseReference(s) {
  let rest = s
