      authority = afterSlashes
      rest = ''
    } else {
      authority = afterSlashes.slice(0, slashIdx)
      rest = afterSlashes.slice(slashIdx)
    }
  }

  return { scheme, authority, path: rest, query, fragment }
}

/** Splits an authority string into userinfo, host and port. */
function splitAuthority(authority) {
  let userinfo = null
  let rest = authority
