  if (atIdx !== -1) {
    userinfo = authority.slice(0, atIdx)
    rest = authority.slice(atIdx + 1)
  }

  const bracketIdx = rest.lastIndexOf(']')
  const searchStart = bracketIdx === -1 ? 0 : bracketIdx + 1
  const colonIdx = rest.indexOf(':', searchStart)
