  // of where in the record the offending component actually appears.
  checkPercentEncoding('path', parts.path)
  checkPercentEncoding('userinfo', userinfo)
  checkPercentEncoding('host', host)
  checkPercentEncoding('query', parts.query)
  checkPercentEncoding('fragment', parts.fragment)

  let path = normalizePercentEncoding(parts.path)
