  if (parts.query !== null) out += '?' + parts.query
  if (parts.fragment !== null) out += '#' + parts.fragment
  return out
}

function mergePaths(base, refPath) {
  if (base.authority !== null && base.path === '') {
    return '/' + refPath
  }
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return base.path.slice(0, idx + 1) + refPath
