/**
 * Resolves a reference against a base per RFC 3986 section 5.2.2 (strict),
 * returning the unnormalized target components. Normalization is a
 * separate, final pass applied uniformly regardless of which branch below
 * produced the result.
 */
export function resolveReference(base, ref) {
  if (ref.scheme !== null) {
    return { scheme: ref.scheme, authority: ref.authority, path: ref.path, query: ref.query, fragment: ref.fragment }
  }

  if (ref.authority !== null) {
    return { scheme: base.scheme, authority: ref.authority, path: ref.path, query: ref.query, fragment: ref.fragment }
  }

  if (ref.path === '') {
    return {
      scheme: base.scheme,
      authority: base.authority,
      path: base.path,
      query: ref.query !== null ? ref.query : base.query,
      fragment: ref.fragment,
    }
  }

  const path = ref.path.startsWith('/') ? ref.path : mergePaths(base, ref.path)
  return { scheme: base.scheme, authority: base.authority, path, query: ref.query, fragment: ref.fragment }
}
