{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { parseReference, normalizeParts, serialize, resolveReference, NoBaseSchemeError } from './uri.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  let bytesRead
  do {
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead > 0) chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  } while (bytesRead > 0)
  return Buffer.concat(chunks).toString('utf8')
}

function splitRecords(input) {
  if (input === '') return []
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

function normalizeRecord(record) {
  const parts = parseReference(record)
  return serialize(normalizeParts(parts))
}

function resolveRecord(record) {
  const spaceIdx = record.indexOf(' ')
  if (spaceIdx === -1) {
    throw new Error('expected a base and a reference')
  }
  const baseStr = record.slice(0, spaceIdx)
  const refStr = record.slice(spaceIdx + 1)

  const base = parseReference(baseStr)
  if (base.scheme === null) {
    throw new NoBaseSchemeError()
  }
  const ref = parseReference(refStr)
  const target = resolveReference(base, ref)
  return serialize(normalizeParts(target))
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const mode = args[0]

  const input = readStdin()
  const records = splitRecords(input)
  const results = []

  for (let i = 0; i < records.length; i++) {
    const lineNo = i + 1
    try {
      const record = records[i]
      results.push(mode === 'normalize' ? normalizeRecord(record) : resolveRecord(record))
    } catch (err) {
      process.stderr.write(`error: line ${lineNo}: ${err.message}\n`)
      process.exit(2)
    }
  }

  process.stdout.write(results.map((line) => line + '\n').join(''))
  process.exit(0)
}

main()
"}

